import { PlaneGeometry, Group, Vector3 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a billboard sprite for the "Pricing card 2 label" element.
 * Produces a textured plane with a MeshBasicNodeMaterial, using the provided
 * ceramic grain texture and applying atlas UV offsets. The text "Pricing 2"
 * is rendered via the font atlas system and placed in front of the plane.
 *
 * @param {Object} config - PrismNode configuration
 * @param {NodeContext} ctx - Runtime context with loaders and primitives
 * @returns {THREE.Group} The assembled node with cleanup and event handlers
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // --- Configuration ---
  const atlasRegion = {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
  };
  const aspect = atlasRegion.width / atlasRegion.height; // ~1.6
  const planeWidth = 1.6;
  const planeHeight = 1.0;

  // --- Geometry ---
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // --- Material (MeshBasicNodeMaterial) ---
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  // --- Texture loading ---
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      // Apply atlas UV offsets relative to the full texture size
      const imgW = tex.image ? tex.image.width : 1;
      const imgH = tex.image ? tex.image.height : 1;
      tex.repeat.set(atlasRegion.width / imgW, atlasRegion.height / imgH);
      tex.offset.set(atlasRegion.x / imgW, 1.0 - (atlasRegion.y + atlasRegion.height) / imgH); // flip Y for WebGL
      tex.needsUpdate = true;

      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Mesh ---
  const mesh = new THREE.Mesh(geometry, material);
  mesh.rotation.y = Math.PI; // flip so that +Z faces the camera after group.lookAt
  group.add(mesh);

  // --- Billboard: orient the group to face the camera ---
  // Assume camera is at (0, 0, 10) per the hub frame specification
  const cameraPosition = new Vector3(0, 0, 10);
  group.lookAt(cameraPosition);

  // --- Text content ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((t) => t.role === 'headline');
  if (headlineItem) {
    const fontSize = headlineItem.typography?.fontSize ?? 39;
    const textMesh = ctx.fontAtlas.createText('Pricing 2', {
      fontSize,
      color: '#e8ecf2',
      align: 'center',
    });
    textMesh.position.set(0, 0, 0.01); // slightly in front of the plane
    group.add(textMesh);
  }

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // No GSAP timelines to kill
  };

  // Position the node (the adapter will also apply config.scenePosition)
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }

  return group;
}
